count-substrings-that-satisfy-k-constrai:
class Solution:
    def countKConstraintSubstrings(self, s: str, k: int) -> int:
        n = len(s)
        ans = 0
        for i in range(n):
            z = o = 0
            for j in range(i, n):
                if s[j] == '0':
                    z += 1
                else:
                    o += 1
                if z > k and o > k:
                    break
                ans += 1
        return ans

