count-the-number-of-incremovable-subarra:
class Solution:
    def incremovableSubarrayCount(self, nums: List[int]) -> int:
        n = len(nums)
        ans = 0
        for i in range(n):
            for j in range(i, n):
                rest = nums[:i] + nums[j + 1:]
                if all(rest[t] < rest[t + 1] for t in range(len(rest) - 1)):
                    ans += 1
        return ans

count-vowel-substrings-of-a-string:
class Solution:
    def countVowelSubstrings(self, word: str) -> int:
        vowels = set('aeiou')
        n = len(word)
        ans = 0
        for i in range(n):
            seen = set()
            for j in range(i, n):
                if word[j] not in vowels:
                    break
                seen.add(word[j])
                if len(seen) == 5:
                    ans += 1
        return ans

