day-of-the-year:
class Solution:
    def dayOfYear(self, date: str) -> int:
        import datetime
        y, m, d = map(int, date.split('-'))
        return (datetime.date(y, m, d) - datetime.date(y, 1, 1)).days + 1

decode-the-message:
class Solution:
    def decodeMessage(self, key: str, message: str) -> str:
        mapping = {}
        for c in key:
            if c != ' ' and c not in mapping:
                mapping[c] = chr(ord('a') + len(mapping))
        return ''.join(' ' if c == ' ' else mapping.get(c, c) for c in message)

