decrypt-string-from-alphabet-to-integer-:
class Solution:
    def freqAlphabets(self, s: str) -> str:
        res = []
        i = 0
        while i < len(s):
            if i + 2 < len(s) and s[i + 2] == '#':
                res.append(chr(96 + int(s[i:i + 2])))
                i += 3
            else:
                res.append(chr(96 + int(s[i])))
                i += 1
        return ''.join(res)

defuse-the-bomb:
class Solution:
    def decrypt(self, code: List[int], k: int) -> List[int]:
        n = len(code)
        if k == 0:
            return [0] * n
        res = []
        for i in range(n):
            if k > 0:
                res.append(sum(code[(i + j) % n] for j in range(1, k + 1)))
            else:
                res.append(sum(code[(i - j) % n] for j in range(1, -k + 1)))
        return res

