design-an-ordered-stream:
class OrderedStream:
    def __init__(self, n: int):
        self.data = {}
        self.ptr = 1
    def insert(self, idKey: int, value: str) -> List[str]:
        self.data[idKey] = value
        out = []
        while self.ptr in self.data:
            out.append(self.data[self.ptr])
            self.ptr += 1
        return out

