class Solution:
    def containsPattern(self, arr: List[int], m: int, k: int) -> bool:
        for i in range(len(arr) - m * k + 1):
            ok = True
            for j in range(m * k):
                if arr[i + j] != arr[i + j % m]:
                    ok = False
                    break
            if ok:
                return True
        return False

