determine-if-string-halves-are-alike:
class Solution:
    def halvesAreAlike(self, s: str) -> bool:
        vowels = set('aeiouAEIOU')
        h = len(s) // 2
        return sum(1 for c in s[:h] if c in vowels) == sum(1 for c in s[h:] if c in vowels)

