determine-the-winner-of-a-bowling-game:
class Solution:
    def isWinner(self, player1: List[int], player2: List[int]) -> int:
        def score(p):
            s = 0
            for i, x in enumerate(p):
                s += x
                if i >= 1 and p[i - 1] == 10:
                    s += x
                elif i >= 2 and p[i - 2] == 10:
                    s += x
            return s
        a = score(player1)
        b = score(player2)
        if a > b:
            return 1
        if b > a:
            return 2
        return 0

